const item = $input.first().json;

return [{
  json: {
    contractText: (item['Paste the contract or terms of service text'] || '').trim(),
    role: item['Your role in this agreement'] || 'Other',
    docType: item['Document type (optional, helps accuracy)'] || 'Not sure / Skip'
  }
}];

const item = $input.first().json;
let text = item.contractText;
let truncated = false;

if (text.length > 14000) {
  text = text.slice(0, 14000);
  truncated = true;
}

return [{
  json: {
    contractText: text,
    role: item.role,
    docType: item.docType,
    truncated
  }
}];

